'use strict';

// MODULES //

var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var MODES = [
	'permissive',
	'strict'
];
var PROFILES = [
	'readme',
	'tutorial',
	'generic'
];
var isMode = contains( MODES );
var isProfile = contains( PROFILES );


// MAIN //

/**
* Validates conversion options.
*
* @private
* @param {Options} opts - conversion options
* @returns {(Error|null)} error or null
*/
function validate( opts ) {
	if ( !isPlainObject( opts ) ) {
		return new TypeError( format( 'invalid argument. Options argument must be a plain object. Value: `%s`.', opts ) );
	}
	if ( hasOwnProp( opts, 'mode' ) && !isMode( opts.mode ) ) {
		return new TypeError( format( 'invalid option. `%s` option must be one of the following: "%s". Option: `%s`.', 'mode', join( MODES, '", "' ), opts.mode ) );
	}
	if ( hasOwnProp( opts, 'profile' ) && !isProfile( opts.profile ) ) {
		return new TypeError( format( 'invalid option. `%s` option must be one of the following: "%s". Option: `%s`.', 'profile', join( PROFILES, '", "' ), opts.profile ) );
	}
	if ( hasOwnProp( opts, 'includePositions' ) && !isBoolean( opts.includePositions ) ) {
		return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'includePositions', opts.includePositions ) );
	}
	if ( hasOwnProp( opts, 'includeSourceSlices' ) && !isBoolean( opts.includeSourceSlices ) ) {
		return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'includeSourceSlices', opts.includeSourceSlices ) );
	}
	return null;
}


// EXPORTS //

module.exports = validate;
